def perform_operation(num1, num2, operation):
    """Perform the specified operation on two numbers and return the result."""
    if operation == '+':
        return num1 + num2
    elif operation == '-':
        return num1 - num2
    elif operation == '*':
        return num1 * num2
    elif operation == '/':
        if num2 == 0:
            raise ValueError("Cannot divide by zero.")
        return num1 / num2
    else:
        raise ValueError(f"Invalid operation: {operation}. Choose from +, -, *, /")

